package glitch

import data.glitch_lib

credential_pattern := "(?i)\\b(password|secret|api[_-]?key|token|access[_-]?key|secret[_-]?key|credential|auth|pass|private[_-]?key|connection[_-]?string|admin[_-]?password|root[_-]?password)\\b"

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [path, node])
    node.ir_type == "KeyValue"

    key_str := get_name(node)
    regex.match(credential_pattern, key_str)

    node.value.ir_type == "String"
    node.value.value != ""

    result := {
        "type": "sec_hard_secr",
        "element": node,
        "path": parent.path,
        "description": "Hard-coded credential found - Avoid using hard-coded credentials in IaC scripts. (CWE-798)"
    }
}

