get_name(node) = str {
    node.ir_type == "KeyValue"
    node.key.ir_type == "String"
    str := node.key.value
} else {
    node.ir_type == "KeyValue"
    node.key.ir_type == "VariableReference"
    str := node.key.value
} else {
    node.ir_type == "Variable"
    str := node.name
} else {
    node.ir_type == "Attribute"
    str := node.name
}
